must(x.imgs.length===7&&x.imgs.every(e=>e.ok),'images '+width);must(x.faq===5,'FAQ '+width);
must(x.area===5&&x.cols===(width>720?2:1),'confirmation grid '+width);
must(x.line.length===8&&x.line.every(z=>z==='https://lin.ee/tsilra6'),'LINE '+width);
must(x.tel.length===3&&x.tel.every(z=>z==='tel:05017241338'),'phone '+width);
