must(x.text.includes('9,000円')&&x.text.includes('15,000円')&&x.text.includes('16,000円')&&x.text.includes('出張費0円')&&!x.text.includes('カビの再発防止'),'price/overclaim '+width);
must(x.navCount===5,'nav5 '+width);if(width===320)must(x.navRows.length===2,'nav 3+2 '+JSON.stringify(x.navRows));
must(x.scroll<=width&&!x.overflow.length&&!errs.length&&!bad.length,'layout '+width+' '+JSON.stringify({scroll:x.scroll,overflow:x.overflow,errors:errs,bad}));
const qs=p.locator('#faq details.faq-details');for(let i=0;i<await qs.count();i++){const q=qs.nth(i),was=await q.evaluate(x=>x.open);await q.locator('summary').click();must((await q.evaluate(x=>x.open))!==was,'FAQ toggle '+i);await q.locator('summary').click();must((await q.evaluate(x=>x.open))===was,'FAQ restore '+i)}
if(width===1440){for(const link of ['/complete-disassembly/','/cursor-test/central.html','/cursor-test/south.html','/cursor-test/cases.html','/cursor-test/faq.html']){const q=await p.request.get('https://teruya1229.github.io'+link,{timeout:25000});must(q.status()===200,'related '+link+' status='+q.status())}}
